  "python": "def pilot_policy(trace):
    action, label = trace[-1]
    args = json.loads(action.arguments) if action.arguments else {}

    support_route = {
        'local': 'slot:internal',
        'partner': 'slot:customer',
        'release': 'slot:public'
    }
    finance_route = {
        'local': 'slot:internal',
        'partner': 'slot:vendor',
        'release': 'slot:control'
    }

    if action.name == 'collector/import_record':
        return None
    elif action.name == 'editor/edit':
        return None
    elif action.name == 'packer/pack':
        return None
    elif action.name == 'finance/dispatch' or action.name == 'support/dispatch':
        route = args.get('route', '')
        mode = args.get('mode', 'standard')
        receipt = args.get('receipt', 'local')
        source = args.get('source', 'bulletin')

        if source == 'bulletin':
            source_has_categories = False
        else:
            source_has_categories = True

        if action.name == 'finance/dispatch':
            primary_slot = finance_route.get(route)
            partner_slot = finance_route.get('partner')
        else:
            primary_slot = support_route.get(route)
            partner_slot = support_route.get('partner')

        destination_slots = {primary_slot}
        if mode == 'mirror':
            destination_slots.add('slot:public')
        if mode == 'linked':
            destination_slots.add(partner_slot)
        if receipt == 'external':
            destination_slots.add('slot:audit')
        if receipt == 'partner':
            if primary_slot != partner_slot:
                destination_slots.add(partner_slot)

        categories = label.subset
        for slot in destination_slots:
            if slot in policy:
                allowed = set(policy[slot])
                if not categories.issubset(allowed):
                    raise PolicyViolation(f"Categories {categories} not allowed in {slot}")
        return None
    else:
        raise PolicyViolation("Unknown tool action")"
